<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$dbn=getenv('DB_NAME')?:'sukamulya_ui_test';if($dbn!=='sukamulya_ui_test')throw new RuntimeException('Only isolated sukamulya_ui_test allowed');
$db=new mysqli('localhost','root','',$dbn);$base='http://127.0.0.1:8097/';$tag='uit'.bin2hex(random_bytes(4));$pw=bin2hex(random_bytes(20));$hash=password_hash($pw,PASSWORD_DEFAULT);
foreach(array('admin','operator','auditor') as $role){$name=$tag.'_'.$role;$s=$db->prepare('INSERT INTO admins(username,password_hash,role,is_active) VALUES(?,?,?,1)');$s->bind_param('sss',$name,$hash,$role);$s->execute();}
function verify_ui($ok,$label){if(!$ok)throw new RuntimeException($label);echo 'PASS '.$label.PHP_EOL;}
class OpsHttp{
 public $c,$html,$code,$location;public function __construct(){$this->c=curl_init();curl_setopt_array($this->c,array(CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>20,CURLOPT_PROXY=>'',CURLOPT_HEADER=>TRUE));}
 function go($path,$fields=NULL){global $base;if($fields!==NULL){$token='';foreach(curl_getinfo($this->c,CURLINFO_COOKIELIST) as $cookie){$p=explode("\t",$cookie);if(($p[5]??'')==='csrf_sukamulya_cookie')$token=$p[6];}$fields['csrf_sukamulya']=$token;curl_setopt_array($this->c,array(CURLOPT_POST=>TRUE,CURLOPT_POSTFIELDS=>http_build_query($fields)));}else curl_setopt($this->c,CURLOPT_HTTPGET,TRUE);curl_setopt($this->c,CURLOPT_URL,$base.$path);$raw=curl_exec($this->c);$size=curl_getinfo($this->c,CURLINFO_HEADER_SIZE);$head=substr($raw,0,$size);$this->html=substr($raw,$size);$this->code=curl_getinfo($this->c,CURLINFO_HTTP_CODE);$this->location=preg_match('/^Location:\s*(\S+)/mi',$head,$m)?$m[1]:'';return $this;}
 function login($role){global $tag,$pw;$this->go('admin/login');$this->go('admin/login',array('username'=>$tag.'_'.$role,'password'=>$pw));verify_ui(in_array($this->code,array(302,303,307),TRUE),'Login '.$role);return $this;}
 function post($path,$data){$this->go($path);$this->go($path,$data);verify_ui(!preg_match('/Fatal error|A PHP Error|A Database Error|Severity:/',$this->html),'POST no PHP errors '.$path);return $this;}
}
$a=(new OpsHttp())->login('admin');
$pages=array('akun'=>'admin/akun','fields'=>'admin/field-tambahan','outbox'=>'admin/antrean-email','handover'=>'admin/serah-terima','audit'=>'admin/audit','backup'=>'admin/backup','settings-history'=>'admin/pengaturan/riwayat','reconciliation'=>'admin/rekonsiliasi');
foreach($pages as $name=>$path){$a->go($path);verify_ui($a->code===200&&!preg_match('/A PHP Error|A Database Error|Fatal error|Severity:/',$a->html),'GET '.$path);$html=str_replace(array($tag.'_admin',ucwords(str_replace('_',' ',$tag.'_admin'))),'Admin',$a->html);file_put_contents(__DIR__.'/../tmp/family-preview/admin-'.$name.'.html',$html);}
// Handover workflow, including rejected early finalization and post-final edit.
/* Form now selects officials by id ('o'+id), see handover_smoke.php; assertion unchanged. */$db->query("INSERT INTO officials(name,position,description,icon,sort_order,is_active) VALUES('Lama $tag','Ketua RT','','x',0,0),('Baru $tag','Ketua RT','','x',0,1)");$o1=$db->insert_id;$o2=$o1+1;register_shutdown_function(function()use($db,$tag){$db->query("DELETE FROM officials WHERE name IN ('Lama $tag','Baru $tag')");});$a->post('admin/serah-terima',array('title'=>'Serah Uji '.$tag,'period_label'=>'2026-2029','outgoing'=>'o'.$o1,'incoming'=>'o'.$o2));$h=$db->query("SELECT * FROM handover_sessions WHERE title='Serah Uji $tag'")->fetch_assoc();verify_ui($h&&$h['status']==='draft'&&hash('sha256',$h['snapshot_json'])===$h['snapshot_hash'],'Handover creates immutable aggregate snapshot');$path='admin/serah-terima/'.$h['id'];
$a->post($path,array('act'=>'finalize'));verify_ui($db->query('SELECT status FROM handover_sessions WHERE id='.(int)$h['id'])->fetch_assoc()['status']==='draft','Incomplete handover cannot be finalized');
$list=json_decode($h['checklist_json'],TRUE);$statuses=array_fill_keys(array_keys($list),'sesuai');$a->post($path,array('act'=>'checklist','status'=>$statuses));$a->post($path,array('act'=>'sign','side'=>'lama'));
$name=$tag.'_ketua';$role='ketua';$s=$db->prepare('INSERT INTO admins(username,password_hash,role,is_active) VALUES(?,?,?,1)');$s->bind_param('sss',$name,$hash,$role);$s->execute();$k=(new OpsHttp())->login('ketua');$k->post($path,array('act'=>'sign','side'=>'baru'));$a->post($path,array('act'=>'finalize'));verify_ui($db->query('SELECT status FROM handover_sessions WHERE id='.(int)$h['id'])->fetch_assoc()['status']==='final','Both parties approve and handover finalizes');$a->post($path,array('act'=>'checklist','status'=>array_fill_keys(array_keys($list),'belum')));verify_ui($db->query('SELECT status FROM handover_sessions WHERE id='.(int)$h['id'])->fetch_assoc()['status']==='final','Final handover stays locked');
// Restore setting only inside disposable DB; actual operational configuration untouched.
$aid=(int)$db->query("SELECT id FROM admins WHERE username='{$tag}_admin'")->fetch_assoc()['id'];$snapshot=json_encode(array('site_name'=>'Restored '.$tag));$note='Uji restore '.$tag;$s=$db->prepare('INSERT INTO settings_history(snapshot_json,note,changed_by) VALUES(?,?,?)');$s->bind_param('ssi',$snapshot,$note,$aid);$s->execute();$history_id=$db->insert_id;$a->post('admin/pengaturan/riwayat',array('history_id'=>$history_id));verify_ui($db->query("SELECT setting_value FROM settings WHERE setting_key='site_name'")->fetch_assoc()['setting_value']==='Restored '.$tag,'Settings restore applies recorded previous values');
// Backup files must be stored in the separate application copy; never rotate operational backups.
$root=dirname(__DIR__).'/tmp/adminqa/application/storage/backups';
$a->post('admin/backup',array('act'=>'run'));$run=$db->query('SELECT * FROM backup_runs ORDER BY id DESC LIMIT 1')->fetch_assoc();verify_ui($run&&$run['status']==='success','Encrypted database backup completes');$file=$root.'/'.$run['file_name'];verify_ui(is_file($file)&&substr(file_get_contents($file),0,5)==='RTBK1','Backup file exists only in isolated storage with encrypted header');
$a->post('admin/backup',array('act'=>'verify','run_id'=>$run['id']));verify_ui((bool)$db->query('SELECT verified_at FROM backup_runs WHERE id='.(int)$run['id'])->fetch_assoc()['verified_at'],'Backup checksum and decryption verification works');$a->go('admin/backup');$a->go('admin/backup',array('act'=>'download','run_id'=>$run['id']));verify_ui($a->code===200&&substr($a->html,0,5)==='RTBK1','Authorized encrypted backup download');
$o=(new OpsHttp())->login('operator');foreach(array('admin/backup','admin/pengaturan/riwayat','admin/serah-terima') as $route){$o->go($route);verify_ui($o->code===403,'Operator denied '.$route);}
$g=new OpsHttp();$g->go('admin/backup');verify_ui(in_array($g->code,array(302,303,307),TRUE),'Guest denied backup');
echo 'All mutations in isolated DB/storage only.'.PHP_EOL;
